def delete_nodes_after_groups(head,m,n):
    current=head
    while current:
        for _ in range(m-1):
            if current.next is None:return head
            current=current.next
        after=current.next
        for _ in range(n):
            if after is None:break
            after=after.next
        current.next=after;current=after
    return head

